type 范围配置 = {
  min: number;
  max: number;
};

type 白名单条目 = {
  type: '百分比' | '整数' | '布尔';
  range?: 范围配置; // 百分比/整数需要
  fixed?: number; // 布尔固定值
};

type 白名单表 = Record<string, 白名单条目>;

