import type { 角色, 技能, 技能效果 } from '../types/role';
import { 角色Schema, 技能Schema } from '../types/role';
import {
  parseAndValidateMod,
  parseAndValidateMods,
  getWhitelistEntry,
  isWhitelisted,
  clampValue,
} from './skillEffectWhitelist';
import { nextRoleId, nextSkillId } from './roleIdGenerator';

// ============================================================================
// CMD 命令类型
// ============================================================================

type CMDResult =
  | { type: 'add_role'; role: 角色 }
  | { type: 'mod_role'; roleId: string; updates: Record<string, unknown> }
  | { type: 'del_role'; roleId: string }
  | { type: 'equip_skill'; roleId: string; skillId: string }
  | { type: 'unequip_skill'; roleId: string; skillId: string }
  | { type: 'add_skill'; skill: 技能 }
  | { type: 'del_skill'; skillId: string };

// ============================================================================
// 正则表达式
// ============================================================================

// 兼容中文/英文冒号和竖线
// 直接用字符串，避免 .source 对 [] 类的解析问题
const COLON = '[::]'; // 匹配一个冒号（英文: 或中文：）
const PIPE = '[||｜]'; // 匹配一个竖线（英文| 或中文｜）

// 匹配 CMD:XXX|... 块，支持多行
const CMD_BLOCK_RE = /<cmd[^>]*>([\s\S]*?)<\/cmd>/gi;
const CMD_BLOCK_RE_NO_TAG = /CMD:([A-Z_]+)\|([\s\S]*?)(?=CMD:[A-Z_]+|<cmd|$)/gi;

// 解析属性格式: "战力:3 技巧:2 智慧:5" 或 "战力：3 技巧：2"
const 属性行RE = new RegExp(
  `(?:(${['战力', '技巧', '智慧', '社交', '谨慎', '运气'].join('|')})${COLON}(\\d+)`, 'g',
);

// 解析 mod:域.键 格式
const MOD_RE = /mod:([^\s,，]+)/g;

// ============================================================================
// 工具函数
// ============================================================================

/**
 * 解析键值对（兼容中英文冒号）
 */
function parseKeyValue(line: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const pairs = line.split(/[||｜]/).filter(Boolean);

  for (const pair of pairs) {
    // 找第一个冒号（兼容中英文）
    const colonIdx = pair.search(/[::]/);
    if (colonIdx < 0) continue;

    const key = pair.slice(0, colonIdx).trim();
    const valueRaw = pair.slice(colonIdx + 1).trim();

    if (!key) continue;

    // 尝试解析数值
    const num = Number(valueRaw);
    if (!isNaN(num) && valueRaw.match(/^\s*-?\d+(\.\d+)?\s*$/)) {
      result[key] = num;
    } else {
      result[key] = valueRaw;
    }
  }

  return result;
}

/**
 * 解析属性行
 */
function parse属性行(text: string): Record<string, number> | null {
  const result: Record<string, number> = {};
  let found = 0;

  const matches = text.matchAll(属性行RE);
  for (const m of matches) {
    const attr = m[1];
    const val = parseInt(m[2], 10);
    if (!isNaN(val)) {
      result[attr] = Math.min(5, Math.max(0, val));
      found++;
    }
  }

  return found > 0 ? result : null;
}

// ============================================================================
// CMD 命令解析
// ============================================================================

/**
 * 从消息文本中提取所有 CMD 命令
 */
export function extractCMDs(text: string): Array<{ cmd: string; body: string; fullMatch: string }> {
  const results: Array<{ cmd: string; body: string; fullMatch: string }> = [];

  // 方案1: <cmd>...</cmd> 标签格式
  for (const m of text.matchAll(CMD_BLOCK_RE)) {
    const inner = m[1].trim();
    const cmdMatch = inner.match(/^CMD:([A-Z_]+)\|(.*)/i);
    if (cmdMatch) {
      results.push({
        cmd: cmdMatch[1].toUpperCase(),
        body: cmdMatch[2],
        fullMatch: m[0],
      });
    }
  }

  // 方案2: 直接 CMD:XXX|... 格式（无标签）
  for (const m of text.matchAll(CMD_BLOCK_RE_NO_TAG)) {
    results.push({
      cmd: m[1].toUpperCase(),
      body: m[2].trim(),
      fullMatch: m[0],
    });
  }

  return results;
}

/**
 * 解析单个 CMD 命令体，返回操作指令
 */
export function parseSingleCMD(cmd: string, body: string): CMDResult | null {
  const bodyTrimmed = body.trim();

  switch (cmd) {
    case 'ADD': {
      // CMD:ADD|姓名:xxx|属性:战力:3 技巧:2 智慧:5|状态:空闲
      const kv = parseKeyValue(bodyTrimmed);

      if (!kv['姓名']) return null;

      const id = nextRoleId();
      const 姓名 = String(kv['姓名']);
      const 状态 = String(kv['状态'] ?? '空闲');

      // 解析属性行
      let 属性: Record<string, number> | undefined;
      const 属性Raw = String(kv['属性'] ?? '');
      if (属性Raw) {
        const parsed = parse属性行(属性Raw);
        if (parsed) 属性 = parsed;
      }

      // 其他键值对全部透传到 catchall
      const roleObj: Record<string, unknown> = {
        id,
        姓名,
        属性: 属性 ?? { 战力: 0, 技巧: 0, 智慧: 0, 社交: 0, 谨慎: 0, 运气: 0 },
        状态,
        已装备技能: [],
        当前任务: null,
        记录: [],
      };

      // 复制其他键值对
      for (const [k, v] of Object.entries(kv)) {
        if (k !== '姓名' && k !== '属性' && k !== '状态') {
          roleObj[k] = v;
        }
      }

      const parsed = 角色Schema.safeParse(roleObj);
      if (!parsed.success) {
        console.error('[roleParser] CMD:ADD 解析失败', parsed.error.format());
        return null;
      }

      return { type: 'add_role', role: parsed.data };
    }

    case 'MOD': {
      // CMD:MOD|角色ID|键:值|键:值
      const segments = bodyTrimmed.split(new RegExp(PIPE)).filter(Boolean);
      if (segments.length < 2) return null;

      const roleId = segments[0].trim();
      const updates: Record<string, unknown> = {};

      for (let i = 1; i < segments.length; i++) {
        const colonIdx = segments[i].search(/[::]/);
        if (colonIdx < 0) continue;
        const key = segments[i].slice(0, colonIdx).trim();
        const valRaw = segments[i].slice(colonIdx + 1).trim();
        const num = Number(valRaw);
        updates[key] = !isNaN(num) && valRaw.match(/^\s*-?\d+(\.\d+)?\s*$/) ? num : valRaw;
      }

      return { type: 'mod_role', roleId, updates };
    }

    case 'DEL': {
      // CMD:DEL|角色ID
      const segments = bodyTrimmed.split(new RegExp(PIPE)).filter(Boolean);
      if (segments.length < 1) return null;
      return { type: 'del_role', roleId: segments[0].trim() };
    }

    case 'EQUIP': {
      // CMD:EQUIP|角色ID|技能ID
      const segments = bodyTrimmed.split(new RegExp(PIPE)).filter(Boolean);
      if (segments.length < 2) return null;
      return { type: 'equip_skill', roleId: segments[0].trim(), skillId: segments[1].trim() };
    }

    case 'UNEQUIP': {
      // CMD:UNEQUIP|角色ID|技能ID
      const segments = bodyTrimmed.split(new RegExp(PIPE)).filter(Boolean);
      if (segments.length < 2) return null;
      return { type: 'unequip_skill', roleId: segments[0].trim(), skillId: segments[1].trim() };
    }

    case 'ADD_SKILL': {
      // CMD:ADD_SKILL|名称:xxx|描述:yyy|mod:域.键
      const kv = parseKeyValue(bodyTrimmed);

      const 名称 = String(kv['名称'] ?? '');
      if (!名称) return null;

      const 描述 = String(kv['描述'] ?? '');
      const emoji = String(kv['emoji'] ?? '');

      // 收集所有 mod:域.键
      const modKeys: string[] = [];
      for (const v of Object.values(kv)) {
        if (typeof v === 'string') {
          const matches = v.matchAll(MOD_RE);
          for (const m of matches) {
            modKeys.push(m[1]);
          }
        }
      }

      const effects: 技能效果[] = [];
      for (const key of modKeys) {
        const effect = parseAndValidateMod(key);
        if (effect) effects.push(effect);
      }

      // 单 mod 限制：只保留第一个
      const limitedEffects = effects.slice(0, 1);
      if (limitedEffects.length === 0) return null;

      const skillObj = {
        id: nextSkillId(),
        名称,
        emoji,
        描述,
        效果: limitedEffects,
      };

      const parsed = 技能Schema.safeParse(skillObj);
      if (!parsed.success) {
        console.error('[roleParser] CMD:ADD_SKILL 解析失败', parsed.error.format());
        return null;
      }

      return { type: 'add_skill', skill: parsed.data };
    }

    case 'DEL_SKILL': {
      // CMD:DEL_SKILL|技能ID
      const segments = bodyTrimmed.split(new RegExp(PIPE)).filter(Boolean);
      if (segments.length < 1) return null;
      return { type: 'del_skill', skillId: segments[0].trim() };
    }

    default:
      return null;
  }
}

/**
 * 从消息文本解析所有 CMD 操作
 */
export function parseMessageCMDs(text: string): CMDResult[] {
  const commands = extractCMDs(text);
  const results: CMDResult[] = [];

  for (const { cmd, body } of commands) {
    const result = parseSingleCMD(cmd, body);
    if (result) results.push(result);
  }

  return results;
}
