    // 初始加载绑定
    _loadBindings();
    // 图片卡牌队列（最多10张）
    const imageCardQueue = ref([]);
    const MAX_IMAGE_CARDS = 10;
    // 记录正在生成的请求
    const activeImageRequests = new Map();
    // 是否有图片生成任务进行中（用于舞台加载态）
    const imageGenerating = ref(false);
    // --- 图像标签解析与手动覆盖 ---
    // 当前显示的图片标题（用于判断 title 变化）
    const currentImageTitle = ref(null);
    // 当前显示的图片类型（用于判断类型变化）
    const currentImageType = ref(null);
    // --- 重试弹窗状态 ---
    const retryPanelOpen = ref(false);
    // --- 相册弹窗状态 ---
    const albumPanelOpen = ref(false);
    function openAlbumPanel() {
        albumPanelOpen.value = true;
    }
    function closeAlbumPanel() {
        albumPanelOpen.value = false;
    }
    // 重试模式：'both' | 'background' | 'cg'
    const retryMode = ref('background');
    // 弹窗内当前激活的标签页（仅在 both 模式下有效）
    const retryActiveTab = ref('background');
    const retryGeneratedImages = ref([]);
    const retrySelectedIndices = ref(new Set());
    // 分别记录背景和 CG 的提示词
    const lastRetryPrompt = ref({});
