// @types 中的酒馆助手函数是 ambient declarations，无需 import
import { klona } from 'klona';

/**
 * 角色 ID / 技能 ID 自增管理
 * 读写酒馆聊天变量中的 role_max_id / skill_max_id
 */

// ============================================================================
// 角色 ID 管理
// ============================================================================

export function getRoleMaxId(): number {
  const vars = getVariables({ type: 'chat' });
  return (vars?.role_max_id as number) ?? 0;
}

export function setRoleMaxId(id: number): void {
  replaceVariables({ role_max_id: id }, { type: 'chat' });
}

export function nextRoleId(): string {
  const current = getRoleMaxId();
  const next = current + 1;
  setRoleMaxId(next);
  return `char_${String(next).padStart(3, '0')}`;
}

export function peekNextRoleId(): string {
  const current = getRoleMaxId();
  return `char_${String(current + 1).padStart(3, '0')}`;
}

// ============================================================================
// 技能 ID 管理
// ============================================================================

export function getSkillMaxId(): number {
  const vars = getVariables({ type: 'chat' });
  return (vars?.skill_max_id as number) ?? 0;
}

export function setSkillMaxId(id: number): void {
  replaceVariables({ skill_max_id: id }, { type: 'chat' });
}

export function nextSkillId(): string {
  const current = getSkillMaxId();
  const next = current + 1;
  setSkillMaxId(next);
  return `skill_${String(next).padStart(3, '0')}`;
}

export function peekNextSkillId(): string {
  const current = getSkillMaxId();
  return `skill_${String(current + 1).padStart(3, '0')}`;
}

// ============================================================================
// 批量写入（用于初始化或重置）
// ============================================================================

export function initIdCounters(roleMaxId: number, skillMaxId: number): void {
  replaceVariables(
    {
      role_max_id: Math.max(0, roleMaxId),
      skill_max_id: Math.max(0, skillMaxId),
    },
    { type: 'chat' },
  );
}
