// @types 中的酒馆助手函数是 ambient declarations，无需 import
import { 角色Schema, 技能Schema, 角色检查点Schema, type 角色, type 技能 } from '../types/role';
import { parseMessageCMDs } from './roleParser';
import { getRoleMaxId, getSkillMaxId } from './roleIdGenerator';
import { klona } from 'klona';
import _ from 'lodash';

// ============================================================================
// 配置
// ============================================================================

const CONFIG = {
  debounceDelay: 800, // ms
  checkpointInterval: 25, // 每隔 N 条消息保存一次检查点
};

// ============================================================================
// 模块级状态
// ============================================================================

let roleDbMap: Record<string, string> = {}; // 姓名 → roleId
let skillDbMap: Record<string, string> = {}; // 名称 → skillId
let roles: Record<string, 角色> = {}; // roleId → 角色对象
let skillsInventory: 技能[] = []; // 技能标签列表

let debounceTimer: ReturnType<typeof setTimeout> | null = null;
let initialized = false;

// ============================================================================
// 工具函数
// ============================================================================

function loadFromTavern(): void {
  const v = getVariables({ type: 'chat' }) as {
    role_db_map?: Record<string, string>;
    role_max_id?: number;
    roles?: Record<string, unknown>;
    skill_db_map?: Record<string, string>;
    skill_max_id?: number;
    skillsInventory?: unknown[];
  };

  roleDbMap = v?.role_db_map ?? {};
  skillDbMap = v?.skill_db_map ?? {};

  if (v?.roles) {
    const parsed = _.mapValues(v.roles, r => {
      const result = 角色Schema.safeParse(r);
      return result.success ? result.data : null;
    });
    roles = _.pickBy(parsed, r => r !== null) as Record<string, 角色>;
  } else {
    roles = {};
  }

  if (Array.isArray(v?.skillsInventory)) {
    skillsInventory = v.skillsInventory
      .map(s => {
        const result = 技能Schema.safeParse(s);
        return result.success ? result.data : null;
      })
      .filter((s): s is 技能 => s !== null);
  } else {
    skillsInventory = [];
  }
}

function persistToTavern(): void {
  replaceVariables(
    {
      role_db_map: klona(roleDbMap),
      role_max_id: getRoleMaxId(),
      roles: klona(roles),
      skill_db_map: klona(skillDbMap),
      skill_max_id: getSkillMaxId(),
      skillsInventory: klona(skillsInventory),
    },
    { type: 'chat' },
  );
}

function getCheckpoint(): ReturnType<typeof 角色检查点Schema.parse> | null {
  const v = getVariables({ type: 'chat' }) as { role_checkpoint?: unknown };
  if (!v?.role_checkpoint) return null;
  try {
    return 角色检查点Schema.parse(v.role_checkpoint);
  } catch {
    return null;
  }
}

function saveCheckpoint(latestMsgId: number): void {
  replaceVariables(
    {
      role_checkpoint: {
        message_id: latestMsgId,
        max_id: getRoleMaxId(),
        db_map: { ...roleDbMap },
      },
    },
    { type: 'chat' },
  );
}

function clearCheckpoint(): void {
  replaceVariables({ role_checkpoint: null }, { type: 'chat' });
}

function shouldSaveCheckpoint(latestMsgId: number): boolean {
  const cp = getCheckpoint();
  if (!cp || cp.message_id == null) return true;
  return latestMsgId - cp.message_id >= CONFIG.checkpointInterval;
}

// ============================================================================
// 扫描单条消息
// ============================================================================

function scanMessage(msg: { message_id?: number; message?: string }): void {
  if (!msg.message) return;

  const commands = parseMessageCMDs(msg.message);

  for (const cmd of commands) {
    switch (cmd.type) {
      case 'add_role': {
        const role = cmd.role;
        roles[role.id] = role;
        roleDbMap[role.姓名] = role.id;
        break;
      }
      case 'mod_role': {
        const existing = roles[cmd.roleId];
        if (existing) {
          const merged = { ...existing, ...cmd.updates };
          const result = 角色Schema.safeParse(merged);
          if (result.success) {
            // 姓名变更时同步 db_map
            if (result.data.姓名 !== existing.姓名) {
              delete roleDbMap[existing.姓名];
              roleDbMap[result.data.姓名] = cmd.roleId;
            }
            roles[cmd.roleId] = result.data;
          }
        }
        break;
      }
      case 'del_role': {
        const role = roles[cmd.roleId];
        if (role) {
          delete roleDbMap[role.姓名];
          delete roles[cmd.roleId];
        }
        break;
      }
      case 'add_skill': {
        const skill = cmd.skill;
        skillsInventory.push(skill);
        skillDbMap[skill.名称] = skill.id;
        break;
      }
      case 'del_skill': {
        skillsInventory = skillsInventory.filter(s => s.id !== cmd.skillId);
        for (const [name, id] of Object.entries(skillDbMap)) {
          if (id === cmd.skillId) delete skillDbMap[name];
        }
        // 同步卸下该技能
        for (const role of Object.values(roles)) {
          if (role.已装备技能.includes(cmd.skillId)) {
            role.已装备技能 = role.已装备技能.filter(id => id !== cmd.skillId);
          }
        }
        break;
      }
      case 'equip_skill': {
        const role = roles[cmd.roleId];
        if (role && !role.已装备技能.includes(cmd.skillId)) {
          role.已装备技能.push(cmd.skillId);
        }
        break;
      }
      case 'unequip_skill': {
        const role = roles[cmd.roleId];
        if (role) {
          role.已装备技能 = role.已装备技能.filter(id => id !== cmd.skillId);
        }
        break;
      }
    }
  }
}

// ============================================================================
// 扫描执行
// ============================================================================

function performScan(mode: 'full' | 'incremental'): void {
  const allMessages = getChatMessages('0-{{lastMessageId}}');
  let scanFromIndex = 0;

  // 加载当前状态
  loadFromTavern();

  if (mode === 'incremental') {
    const cp = getCheckpoint();

    if (cp && cp.message_id != null) {
      const cpMsgId = cp.message_id;
      scanFromIndex = allMessages.findIndex(m => (m.message_id ?? 0) > cpMsgId);
      if (scanFromIndex === -1) return;

      Object.assign(roleDbMap, cp.db_map);
    } else {
      mode = 'full';
      scanFromIndex = 0;
    }
  }

  if (mode === 'full') {
    roleDbMap = {};
    roles = {};
    skillDbMap = {};
    skillsInventory = [];
  }

  const messagesToScan = allMessages.slice(scanFromIndex);
  for (const msg of messagesToScan) {
    scanMessage(msg);
  }

  persistToTavern();

  const lastMsgId = allMessages[allMessages.length - 1]?.message_id ?? 0;
  if (shouldSaveCheckpoint(lastMsgId)) {
    saveCheckpoint(lastMsgId);
  }

  console.info(`[roleScanner] ${mode} scan done: ${Object.keys(roles).length} roles, ${skillsInventory.length} skills`);
}

// ============================================================================
// 防抖调度
// ============================================================================

function scheduleScan(mode: 'incremental' | 'full'): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => performScan(mode), CONFIG.debounceDelay);
}

// ============================================================================
// 初始化
// ============================================================================

export function initRoleScanner(): void {
  if (initialized) return;
  initialized = true;

  if (typeof tavern_events === 'undefined') {
    console.warn('[roleScanner] tavern_events 不可用，跳过事件监听');
    return;
  }

  // 新消息到来：增量扫描
  eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => scheduleScan('incremental'));

  // 删楼/回滚/修改楼层：全量扫描
  (
    [tavern_events.MESSAGE_DELETED, tavern_events.MESSAGE_SWIPED, tavern_events.MESSAGE_UPDATED] as (
      | keyof typeof tavern_events
      | string
    )[]
  ).forEach(e => {
    eventOn(e, () => {
      clearCheckpoint();
      scheduleScan('full');
    });
  });

  // 生成开始：优先增量，无检查点则全量
  eventOn('generation_started', () => {
    const cp = getCheckpoint();
    scheduleScan(cp ? 'incremental' : 'full');
  });

  // 切换聊天：全量扫描
  eventOn(tavern_events.CHAT_CHANGED, () => {
    clearCheckpoint();
    scheduleScan('full');
  });

  // 启动：根据检查点决定扫描模式
  const cp = getCheckpoint();
  if (cp && cp.message_id != null) {
    scheduleScan('incremental');
  } else {
    scheduleScan('full');
  }
}

// ============================================================================
// 手动触发
// ============================================================================

export function manualFullScan(): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  performScan('full');
}

// ============================================================================
// 导出状态访问器（供其他模块使用）
// ============================================================================

export function getRoles(): Record<string, 角色> {
  loadFromTavern();
  return roles;
}

export function getRoleById(id: string): 角色 | undefined {
  loadFromTavern();
  return roles[id];
}

export function getRoleByName(name: string): 角色 | undefined {
  loadFromTavern();
  const id = roleDbMap[name];
  return id ? roles[id] : undefined;
}

export function getSkills(): 技能[] {
  loadFromTavern();
  return skillsInventory;
}

export function getSkillById(id: string): 技能 | undefined {
  loadFromTavern();
  return skillsInventory.find(s => s.id === id);
}

export function getSkillByName(name: string): 技能 | undefined {
  loadFromTavern();
  const id = skillDbMap[name];
  return id ? skillsInventory.find(s => s.id === id) : undefined;
}
